create or replace function public.enqueue_anime(items jsonb, p_reason text, p_priority int default 0) returns int language plpgsql security definer set search_path=public as $$ declare n int; begin insert into public.anime_import_queue(anilist_id,reason,priority,snapshot) select (i->>'anilist_id')::bigint,p_reason,p_priority,i->'snapshot' from jsonb_array_elements(items) i on conflict(anilist_id) do update set status=case when public.anime_import_queue.status in('done','not_found','error') and coalesce(public.anime_import_queue.processed_at,'epoch'::timestamptz)<now()-interval '6 hours' then 'pending' else public.anime_import_queue.status end,next_attempt_at=case when public.anime_import_queue.status in('done','not_found','error') and coalesce(public.anime_import_queue.processed_at,'epoch'::timestamptz)<now()-interval '6 hours' then now() else public.anime_import_queue.next_attempt_at end,priority=greatest(public.anime_import_queue.priority,excluded.priority),snapshot=coalesce(excluded.snapshot,public.anime_import_queue.snapshot); get diagnostics n=row_count; return n; end $$;
create or replace function public.claim_import_batch(batch int) returns setof public.anime_import_queue language plpgsql security definer set search_path=public as $$ begin return query update public.anime_import_queue q set status='processing',attempts=q.attempts+1,processed_at=now() where q.anilist_id in(select anilist_id from public.anime_import_queue where(status='pending' and next_attempt_at<=now()) or(status='processing' and processed_at<now()-interval '10 minutes') order by priority desc,next_attempt_at asc limit batch for update skip locked) returning q.*; end $$;
create or replace function public.claim_sync_batch(batch int) returns setof public.pending_sync language plpgsql security definer set search_path=public as $$ begin return query update public.pending_sync p set status='processing',attempts=p.attempts+1,processed_at=now() where p.id in(select id from public.pending_sync where(status='pending' and next_attempt_at<=now()) or(status='processing' and processed_at<now()-interval '10 minutes') order by next_attempt_at asc limit batch for update skip locked) returning p.*; end $$;
revoke all on function public.enqueue_anime(jsonb,text,int),public.claim_import_batch(int),public.claim_sync_batch(int) from public,anon,authenticated; grant execute on function public.enqueue_anime(jsonb,text,int),public.claim_import_batch(int),public.claim_sync_batch(int) to service_role;
